20	// ---- Proxy settings editors: listeners, options, history logging, match & replace ------------
21	//
22	// Every write is a two-step reviewed call, the settings-write shape (ui2_settings_write.go): the
23	// confirm step builds the EXACT API call from the form, holds it server-side, and renders a
24	// review whose projection is the held bytes; the run step spends the entry (LoadAndDelete),
25	// compares the token in constant time, re-reads the state the call overwrites and refuses on
26	// drift, then dispatches the held call verbatim. Whether the call needs the confirmation gate is
27	// derived from the API route's risk class: a gated route gets a gate-minted token and runs
28	// through the guarded chain; an ungated (riskLocal) route gets a ui2-local one-use handle and
29	// runs through the internal mux. Today every route here is riskLocal.
30	
31	const ui2ProxyReviewCap = 8
32	
33	type ui2ProxyReview struct {
34		area     string
35		token    string
36		gated    bool
37		method   string
38		callURL  string
39		body     []byte
40		snap     func(*Server) (string, error)
41		snapshot string
42		driftMsg string
43		expires  time.Time
44	}
45	
46	// ui2ProxyCall is what a per-area parser produces: the exact call plus its review copy.
47	type ui2ProxyCall struct {
48		area         string
49		method       string
50		callURL      string
51		body         []byte
52		title        string
53		consequences []string
54		snap         func(*Server) (string, error) // state the call overwrites; nil when absolute
55		driftMsg     string
56	}
57	
58	// ui2ProxyNeedsGate derives the gate requirement from the API route's manifest risk class. An
59	// unknown route fails closed (gated): its mint then fails and the review is refused.
60	func ui2ProxyNeedsGate(callURL string) bool {
61		path := callURL
62		if i := strings.IndexByte(path, '?'); i >= 0 {
63			path = path[:i]
64		}
65		_, risk, ok := routeRiskFor(path)
66		return !ok || needsConfirmation(risk)
67	}
68	
69	// ui2ProxyCanonicalField reads one console GET and returns the canonical JSON of one top-level
70	// field: counters and traffic-driven figures sit beside the state and must not read as drift.
71	func (s *Server) ui2ProxyCanonicalField(path, field string) (string, error) {
72		rec := newRecorder()
73		s.mux.ServeHTTP(rec, newReq(http.MethodGet, path))
74		if rec.Code != http.StatusOK {
75			return "", fmt.Errorf("reading %s answered %d", path, rec.Code)
76		}
77		var m map[string]any
78		if err := json.Unmarshal(rec.Body.Bytes(), &m); err != nil {
79			return "", fmt.Errorf("reading %s: %v", path, err)
80		}
81		b, err := json.Marshal(m[field])
82		if err != nil {
83			return "", err
84		}
85		return string(b), nil
86	}
