109	// ui2ProxyConfirm holds one call for review and renders the review sheet.
110	func (s *Server) ui2ProxyConfirm(w http.ResponseWriter, r *http.Request, view string, call ui2ProxyCall) {
111		fail := func(msg string) { ui2ProxyReviewFail(w, r, view, msg) }
112		snapshot := ""
113		if call.snap != nil {
114			snap, err := call.snap(s)
115			if err != nil {
116				fail("could not read the current state to review against: " + err.Error())
117				return
118			}
119			snapshot = snap
120		}
121		gated := ui2ProxyNeedsGate(call.callURL)
122		token := ""
123		if gated {
124			path := call.callURL
125			if i := strings.IndexByte(path, '?'); i >= 0 {
126				path = path[:i]
127			}
128			tok, _, errText := s.ui2MintConfirm(path, call.method, call.callURL, call.body)
129			if errText != "" || tok == "" {
130				fail("the confirmation gate refused to mint a review - try again")
131				return
132			}
133			token = tok
134		} else {
135			local, err := randomHex(16)
136			if err != nil {
137				fail("review token: " + err.Error())
138				return
139			}
140			token = local
141		}
142		id, err := randomHex(16)
143		if err != nil {
144			fail("review id: " + err.Error())
145			return
146		}
147		now := time.Now()
148		count := 0
149		s.ui2ProxyReviews.Range(func(k, v any) bool {
150			if e, ok := v.(ui2ProxyReview); ok && now.After(e.expires) {
151				s.ui2ProxyReviews.Delete(k)
152			} else {
153				count++
154			}
155			return true
156		})
157		if count >= ui2ProxyReviewCap {
158			fail("too many reviews are open at once - confirm or let some expire, then try again")
159			return
160		}
161		s.ui2ProxyReviews.Store(id, ui2ProxyReview{
162			area: call.area, token: token, gated: gated, method: call.method, callURL: call.callURL,
163			body: call.body, snap: call.snap, snapshot: snapshot, driftMsg: call.driftMsg,
164			expires: now.Add(ConfirmTTL),
165		})
166		// The projection is the held bytes, pretty-printed: what the run dispatches, in full.
167		projection := call.method + " " + call.callURL
168		if call.body != nil {
169			var v any
170			if json.Unmarshal(call.body, &v) == nil {
171				if pretty, err := json.MarshalIndent(v, "", "  "); err == nil {
172					projection += "\n" + string(pretty)
173				} else {
174					projection += "\n" + string(call.body)
175				}
176			} else {
177				projection += "\n" + string(call.body)
178			}
179		}
180		ui2Fragment(w, r, "burpsy /ui2/ — Proxy", view, ui2Exec("proxy_review.html", map[string]any{
181			"area":         call.area,
182			"title":        call.title,
183			"review_id":    id,
184			"token":        token,
185			"gated":        gated,
186			"projection":   projection,
187			"consequences": call.consequences,
188			"snapshotted":  call.snap != nil,
189		}))
190	}
191	
192	// ui2ProxyRun spends a held review and dispatches it, then re-renders the area's page.
193	func (s *Server) ui2ProxyRun(w http.ResponseWriter, r *http.Request, area string) {
194		render := ui2ProxyRenderers[area]
195		fail := func(msg string) { render(s, w, r, ui2ProxyNote{Error: msg}) }
196		_ = r.ParseForm()
197		v, ok := s.ui2ProxyReviews.LoadAndDelete(r.PostFormValue("review_id"))
198		entry, isReview := v.(ui2ProxyReview)
199		if !ok || !isReview || entry.area != area {
200			fail("that review is unknown or was already used - review the change again")
201			return
202		}
203		if time.Now().After(entry.expires) {
204			fail("that review expired with the confirmation window - review the change again")
205			return
206		}
207		if subtle.ConstantTimeCompare([]byte(entry.token), []byte(r.PostFormValue("token"))) != 1 {
208			fail("that review does not match this confirmation - review the change again")
209			return
210		}
211		if entry.snap != nil {
212			now, err := entry.snap(s)
213			if err != nil {
214				fail("could not re-read the current state to confirm against: " + err.Error())
215				return
216			}
217			if now != entry.snapshot {
218				fail(entry.driftMsg)
219				return
220			}
221		}
222		req := newReq(entry.method, entry.callURL)
223		if entry.body != nil {
224			req.Header.Set("Content-Type", "application/json")
225			req.Body = ioNopCloser(strings.NewReader(string(entry.body)))
226		}
227		rec := newRecorder()
228		if entry.gated {
229			req.Header.Set(ConfirmHeader, entry.token)
230			req.Host = "127.0.0.1"
231			req.Header.Set("Origin", "http://127.0.0.1")
232			s.guarded.ServeHTTP(rec, req)
233		} else {
234			s.mux.ServeHTTP(rec, req)
235		}
236		if rec.Code/100 != 2 {
237			fail("the API refused the change: " + truncateForDisplay(strings.TrimSpace(rec.Body.String()), 300))
238			return
239		}
240		render(s, w, r, ui2ProxyNote{OK: "Saved: " + entry.method + " " + entry.callURL + " answered " + strconv.Itoa(rec.Code) + "."})
241	}
