277	// ui2ProxyCounterRows renders every outcome counter; a counter this table does not name is
278	// still listed by its wire key, so nothing the engine counts is hidden.
279	func ui2ProxyCounterRows(opts map[string]any) []ui2ProxyCounterRow {
280		counters, _ := opts["counters"].(map[string]any)
281		if counters == nil {
282			return nil
283		}
284		seen := map[string]bool{}
285		var out []ui2ProxyCounterRow
286		for _, c := range ui2ProxyCounterLabels {
287			seen[c.key] = true
288			if v, ok := counters[c.key]; ok {
289				out = append(out, ui2ProxyCounterRow{Key: c.key, Label: c.label, Detail: c.detail, Value: ui2ProxyNum(v)})
290			}
291		}
292		var extra []string
293		for k := range counters {
294			if !seen[k] {
295				extra = append(extra, k)
296			}
297		}
298		sort.Strings(extra)
299		for _, k := range extra {
300			out = append(out, ui2ProxyCounterRow{Key: k, Label: k, Value: ui2ProxyNum(counters[k])})
301		}
302		return out
303	}
