340				}
341				v.Effective = globalInvisible
342				if l.Invisible != nil {
343					v.Effective = *l.Invisible
344				}
345				if l.RedirectHost != "" || l.RedirectPort != 0 {
346					host, port := l.RedirectHost, "(client's port)"
347					if host == "" {
348						host = "(client's host)"
349					}
350					if l.RedirectPort != 0 {
351						port = strconv.Itoa(int(l.RedirectPort))
352					}
353					v.Redirect = host + ":" + port
354				}
355				v.Form = ui2ListenerForm{Bind: l.Bind, RedirectHost: l.RedirectHost, Invisible: v.Invisible, ForceTLS: l.ForceTLS, HTTP2: v.HTTP2}
356				if l.RedirectPort != 0 {
357					v.Form.RedirectPort = strconv.Itoa(int(l.RedirectPort))
358				}
359				rows = append(rows, v)
360			}
361			model["rows"] = rows
362			model["add_form"] = ui2ListenerForm{Invisible: "inherit", HTTP2: true}
363		}
364		ui2Fragment(w, r, "burpsy /ui2/ — Proxy listeners", "proxy-listeners", ui2Exec("proxy_listeners.html", model))
