427	func (s *Server) ui2ParseListenerCall(r *http.Request) (ui2ProxyCall, string) {
428		c := ui2ProxyCall{
429			area:     "listeners",
430			title:    "Proxy listener",
431			snap:     ui2ProxySnap("/api/proxy/listener", "listeners"),
432			driftMsg: "the listeners changed between your review and this confirmation - review the current listeners and save again",
433		}
434		rows, ok := s.ui2ListenerRows()
435		if !ok {
436			return c, "no proxy server is attached, so there are no listeners to change"
437		}
438		op := r.PostFormValue("op")
439		id := strings.TrimSpace(r.PostFormValue("id"))
440		if op == "edit" || op == "remove" {
441			if !ui2ListenerIDPattern.MatchString(id) {
442				return c, "that is not a listener id"
443			}
444			row, found := rows[id]
445			if !found {
446				return c, "no listener " + id + " is serving - the page may be stale; reload it"
447			}
448			if op == "remove" {
449				if !row.Removable {
450					return c, "listener " + id + " is the one -proxy-bind opened: it can be re-bound but not removed"
451				}
452				c.method = http.MethodDelete
453				c.callURL = "/api/proxy/listener?id=" + url.QueryEscape(id)
454				c.consequences = []string{
455					"Listener " + id + " (" + row.BoundAddr + ") stops accepting connections immediately; exchanges it is already relaying run to completion.",
456				}
457				return c, ""
458			}
459		}
460		if op != "add" && op != "edit" {
461			return c, "unknown listener operation"
462		}
463		body := ui2ProxyListenerWire{
464			Bind:         strings.TrimSpace(r.PostFormValue("bind")),
465			RedirectHost: strings.TrimSpace(r.PostFormValue("redirect_host")),
466			ForceTLS:     r.PostFormValue("force_tls") != "",
467		}
468		if p := strings.TrimSpace(r.PostFormValue("redirect_port")); p != "" {
469			n, err := strconv.Atoi(p)
470			if err != nil {
471				return c, "the redirect port must be a number between 0 and 65535; leave it blank to keep the client's port"
472			}
473			body.RedirectPort = n
474		}
475		switch r.PostFormValue("invisible") {
476		case "", "inherit":
477		case "on":
478			t := true
479			body.Invisible = &t
480		case "off":
481			f := false
482			body.Invisible = &f
483		default:
484			return c, "invisible proxying must be inherit, on or off"
485		}
486		if r.PostFormValue("support_http2") == "" {
487			f := false
488			body.SupportHTTP2 = &f
489		}
490		// Validate with the API's own spec check so a bad value is refused at review, not at run.
491		port := body.RedirectPort
492		if _, err := specFromBody(proxyListenerBody{
493			Bind: body.Bind, RedirectHost: body.RedirectHost, RedirectPort: &port,
494			ForceTLS: &body.ForceTLS, Invisible: body.Invisible, SupportHTTP2: body.SupportHTTP2,
495		}); err != nil {
496			return c, err.Error()
497		}
498		c.body, _ = json.Marshal(body)
499		if op == "add" {
500			c.method = http.MethodPost
501			c.callURL = "/api/proxy/listener"
502			c.consequences = append(c.consequences, "A new listener opens on "+body.Bind+" as soon as you confirm. A bind that fails adds nothing and you will see the reason.")
503		} else {
504			c.method = http.MethodPut
505			c.callURL = "/api/proxy/listener?id=" + url.QueryEscape(id)
506			c.consequences = append(c.consequences, "Listener "+id+" is replaced with these settings. A changed bind opens the new socket before closing the old one, so a failed move leaves it serving where it was.")
507		}
508		if body.RedirectHost != "" || body.RedirectPort != 0 {
509			c.consequences = append(c.consequences, "Every request this listener accepts is sent to the redirect target instead of the host/port the client named; the Host header is not rewritten.")
510		}
511		if body.ForceTLS {
512			c.consequences = append(c.consequences, "The leg to the destination uses TLS whatever the client used.")
513		}
514		c.consequences = append(c.consequences, "Not persisted: a restart reverts to the single listener -proxy-bind names.")
515		return c, ""
516	}
