651	// ui2ParseOptionsCall builds a diff-only PUT: only the switches the operator changed relative to
652	// the state the form was drawn from (was_<key>), so a stale page never writes back other keys.
653	func (s *Server) ui2ParseOptionsCall(r *http.Request) (ui2ProxyCall, string) {
654		c := ui2ProxyCall{
655			area:     "options",
656			title:    "Proxy options",
657			method:   http.MethodPut,
658			callURL:  "/api/proxy/options",
659			snap:     ui2ProxySnap("/api/proxy/options", "options"),
660			driftMsg: "the proxy options changed between your review and this confirmation - review the current options and save again",
661		}
662		_, live, ok := s.ui2ProxyLiveOptions()
663		if !ok {
664			return c, "no proxy option set is attached to this server"
665		}
666		diff := map[string]bool{}
667		var keys []string
668		for _, k := range proxy.OptionKeys {
669			key := string(k)
670			was := r.PostFormValue("was_" + key)
671			if was == "" {
672				continue // not on the submitted form
673			}
674			wasOn := was == "true"
675			on := r.PostFormValue("opt_"+key) != ""
676			if on == wasOn {
677				continue
678			}
679			if live[key] != wasOn {
680				return c, ui2ProxyOptionLabel(key) + " changed since this page was loaded - reload it and edit again"
681			}
682			diff[key] = on
683			keys = append(keys, key)
684		}
685		if len(diff) == 0 {
686			return c, "nothing changed - tick or untick a switch first"
687		}
688		c.body, _ = json.Marshal(diff)
689		for _, k := range keys {
690			state := "OFF"
691			if diff[k] {
692				state = "ON"
693			}
694			c.consequences = append(c.consequences, ui2ProxyOptionLabel(k)+" turns "+state+" - live, from the next matching message.")
695		}
696		c.consequences = append(c.consequences, "Only these keys are sent; every other switch is left as it is.")
697		return c, ""
698	}
