827		for i := 0; i < n; i++ {
828			p := "r" + strconv.Itoa(i) + "_"
829			cat := "literal"
830			if r.PostFormValue(p+"cat") == "regex" {
831				cat = "regex"
832			}
833			d.Set.Rules = append(d.Set.Rules, matchReplaceRuleSpec{
834				RuleType:      r.PostFormValue(p + "type"),
835				Enabled:       r.PostFormValue(p+"enabled") != "",
836				StringMatch:   r.PostFormValue(p + "match"),
837				StringReplace: r.PostFormValue(p + "replace"),
838				Category:      cat,
839				Comment:       r.PostFormValue(p + "comment"),
840			})
841		}
842		d.Set.UpdateContentLength = r.PostFormValue("ucl") != ""
843		d.Set.InScopeOnly = r.PostFormValue("in_scope") != ""
