976	// ui2MREdit applies one draft operation (?op=add|del|dup|up|down&i=<index>&set=request|response).
977	// Nothing is saved: the draft round-trips through the form until the reviewed save.
978	func ui2MREdit(d *ui2MRDraft, q url.Values) string {
979		rules := d.Set.Rules
980		op := q.Get("op")
981		if op == "add" {
982			if len(rules) >= ui2MRMaxRules {
983				return "a rule set holds at most " + strconv.Itoa(ui2MRMaxRules) + " rules on this page"
984			}
985			t := "request_header"
986			if q.Get("set") == "response" {
987				t = "response_header"
988			}
989			d.Set.Rules = append(rules, matchReplaceRuleSpec{RuleType: t, Enabled: true, Category: "literal"})
990			return ""
991		}
992		i, err := strconv.Atoi(q.Get("i"))
993		if err != nil || i < 0 || i >= len(rules) {
994			return "that rule is not on this draft - reload the editor"
995		}
996		set := ui2MRSet(rules[i].RuleType)
997		switch op {
998		case "del":
999			d.Set.Rules = append(rules[:i:i], rules[i+1:]...)
1000		case "dup":
1001			if len(rules) >= ui2MRMaxRules {
1002				return "a rule set holds at most " + strconv.Itoa(ui2MRMaxRules) + " rules on this page"
1003			}
1004			out := append([]matchReplaceRuleSpec{}, rules[:i+1]...)
1005			out = append(out, rules[i])
1006			d.Set.Rules = append(out, rules[i+1:]...)
1007		case "up", "down":
1008			// Order is per set: swap with the nearest rule of the same set, so the other set's
1009			// relative order (the only order that affects it) never changes.
1010			step := -1
1011			if op == "down" {
1012				step = 1
1013			}
1014			for j := i + step; j >= 0 && j < len(rules); j += step {
1015				if ui2MRSet(rules[j].RuleType) == set {
1016					rules[i], rules[j] = rules[j], rules[i]
1017					return ""
1018				}
1019			}
1020		default:
1021			return "unknown draft operation"
1022		}
1023		return ""
1024	}
1025	
1026	func (s *Server) ui2ParseMRCall(d ui2MRDraft) (ui2ProxyCall, string) {
1027		c := ui2ProxyCall{
1028			area:     "match-replace",
1029			title:    "Match & Replace rules",
1030			method:   http.MethodPut,
1031			callURL:  "/api/tools/rules",
1032			snap:     ui2MRSnap,
1033			driftMsg: "the saved rules changed between your review and this confirmation - revert to load the current set and edit again",
1034		}
1035		saved, err := s.ui2MRSaved()
1036		if err != nil {
1037			return c, err.Error()
1038		}
1039		if ui2MRHash(saved.Config) != d.Baseline {
1040			return c, "the saved rules changed since this editor was loaded - revert to load the current set (your draft is not saved)"
1041		}
1042		if ui2MRHash(d.Set) == d.Baseline {
1043			return c, "nothing changed - the draft equals the saved rule set"
1044		}
1045		// Dry-run the draft through the test route: it compiles every rule exactly as the PUT does,
1046		// so an invalid rule is refused here with its index instead of at run.
1047		if _, errText := s.ui2APIResult(http.MethodPost, "/api/tools/rules/test", matchReplaceTestReq{DraftRules: d.Set.Rules}); errText != "" {
1048			return c, ui2APIErrorText(errText)
1049		}
1050		c.body, _ = json.Marshal(d.Set)
1051		reqN, respN, on := 0, 0, 0
1052		for _, rule := range d.Set.Rules {
1053			if rule.Enabled {
1054				on++
1055			}
1056			if ui2MRSet(rule.RuleType) == "response" {
1057				respN++
1058			} else {
1059				reqN++
1060			}
1061		}
1062		c.consequences = []string{
1063			fmt.Sprintf("The whole saved set (%d rules) is replaced by these %d rules: %d request-side, %d response-side, %d enabled. Live traffic is rewritten by them from the moment you confirm.",
1064				len(saved.Config.Rules), len(d.Set.Rules), reqN, respN, on),
1065			fmt.Sprintf("Fix Content-Length: %t. Only apply to in-scope items: %t.", d.Set.UpdateContentLength, d.Set.InScopeOnly),
1066		}
1067		return c, ""
1068	}
