// ui2APIErrorText renders an API error body for display: the error sentence plus the hint
// when one came back, never the raw JSON blob — the blob's escaped angle brackets and nested
// status dump bury the actual refusal (browser UAT caught the collaborator mint refusal
// rendering as one unreadable JSON line). A body that is not the API's error shape falls
// back to the raw text unchanged: an ugly refusal the operator can read beats a hidden one.
func ui2APIErrorText(errText string) string {
	req.Body = ioNopCloser(strings.NewReader(string(payload)))
	rec := newRecorder()
	// The mint endpoints live on confirmMux (a separate mux the guarded chain consults first);
	// dispatch the internal mint straight to it — an in-process call needs no origin headers.
	s.confirmMux.ServeHTTP(rec, req)
	var minted struct {
		Token string `json:"token"`
		Call  struct {
			Method string `json:"method"`
			URL    string `json:"url"`
			Body   string `json:"body"`
		} `json:"call"`
	}
	if err := ui2DecodeJSON(rec.Body.Bytes(), &minted); err != nil {
		return "", "", "bad mint response: " + err.Error()
	}
	preview = fmt.Sprintf("%s %s", minted.Call.Method, minted.Call.URL)
	if minted.Call.Body != "" {
		preview += " — body " + truncateForDisplay(minted.Call.Body, 200)
	}
	return minted.Token, preview, ""
}

